import { DEV } from "solid-js";
import { formAction } from "./action.js";
/**
 * @deprecated Renamed to `formAction` (the router's action is the form layer;
 * `action` is solid-js's own primitive). Will be removed in the next major.
 */
export const action = /* #__PURE__ */ (() => {
    if (!DEV)
        return formAction;
    let warned = false;
    const wrapped = function (...args) {
        if (!warned) {
            warned = true;
            console.warn("[@solidjs/router] `action` is deprecated and will be removed in the next major; use `formAction` instead.");
        }
        return formAction.apply(this, args);
    };
    return wrapped;
})();
